'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { motion } from 'framer-motion';
import type { ItemAudio } from '@/content/types';

type PlayState = 'idle' | 'playing' | 'error';

/**
 * Big friendly speaker button that plays a pre-seeded English clip
 * (public/audio/tts/en/<key>.wav — generated by `npm run seed:tts -- --only
 * ingliz`). Falls back to the browser's en-US speech synthesis when the cached
 * file is missing (e.g. before the seed has been run), so lessons stay usable
 * in dev. Never calls a TTS API.
 */
export default function AudioButton({
  audio,
  size = 'lg',
  label
}: {
  audio: ItemAudio;
  /** lg = the main "listen" control under a prompt · sm = inline (dialog lines) */
  size?: 'lg' | 'sm';
  label?: string;
}) {
  const [state, setState] = useState<PlayState>('idle');
  const elRef = useRef<HTMLAudioElement | null>(null);
  const startedRef = useRef(false);

  const stop = useCallback(() => {
    elRef.current?.pause();
    if (elRef.current) elRef.current.currentTime = 0;
    setState('idle');
  }, []);

  const playClip = useCallback(async () => {
    if (state === 'playing') {
      stop();
      return;
    }
    try {
      const el = new Audio(`/audio/tts/en/${audio.key}.wav`);
      elRef.current = el;
      el.onended = () => setState('idle');
      await el.play();
      setState('playing');
    } catch {
      // Clip not seeded yet, or the browser blocked autoplay before a tap.
      // Stay silent — never fall back to the robotic browser voice.
      setState('idle');
    }
  }, [state, stop, audio.key]);

  // optional one-shot autoplay when the item appears
  useEffect(() => {
    if (audio.autoplay && !startedRef.current) {
      startedRef.current = true;
      playClip();
    }
    return stop;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [audio.key]);

  const big = size === 'lg';
  return (
    <motion.button
      type="button"
      onClick={playClip}
      whileTap={{ scale: 0.94 }}
      aria-label={label ?? 'Play'}
      className={`inline-flex items-center justify-center gap-2 rounded-full font-black text-white shadow-lg select-none
        focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-brand-blue/40 active:scale-95 transition-transform
        ${big ? 'px-7 py-3.5 text-2xl' : 'w-10 h-10 text-lg shrink-0'}`}
      style={{
        background: state === 'playing' ? 'linear-gradient(135deg,#12a6a0,#1fa7e0)' : 'linear-gradient(135deg,#1fa7e0,#7c5cff)'
      }}
    >
      {state === 'playing' ? (
        <span className="flex items-end gap-[3px] h-5" aria-hidden>
          {[0, 1, 2].map((i) => (
            <motion.span
              key={i}
              className="w-[5px] bg-white rounded-full"
              animate={{ height: [8, 20, 10] }}
              transition={{ repeat: Infinity, duration: 0.6, delay: i * 0.15 }}
            />
          ))}
        </span>
      ) : (
        <span aria-hidden>🔊</span>
      )}
      {big && label && <span className="text-base">{label}</span>}
    </motion.button>
  );
}
